51	pub struct Tmp101Device {
52	    address: u8,
53	    pointer: u8,
54	    config: u8,
55	    /// Configured temperature in °C. Quantized at read time using the
56	    /// current config resolution, so set-then-reconfigure works.
57	    temperature: f32,
58	    /// Datasheet defaults: 75°C / 80°C in 12-bit register layout.
59	    t_low: u16,
60	    t_high: u16,
61	    /// Byte index within the current write transaction. 0 = next byte
62	    /// is the pointer; 1+ = data bytes for the selected register.
63	    write_idx: u8,
64	    /// Byte index within the current read transaction.
65	    read_idx: u8,
66	}
67	
68	impl Tmp101Device {
69	    pub fn new(address: u8) -> Self {
70	        Self {
71	            address: address & 0x7F,
72	            pointer: 0,
73	            config: 0,
74	            temperature: 0.0,
75	            t_low: 0x4B00,
76	            t_high: 0x5000,
77	            write_idx: 0,
78	            read_idx: 0,
79	        }
80	    }
81	
82	    /// Set the configured temperature in °C. Quantized at read time
83	    /// based on the current resolution mode.
84	    pub fn set_temperature(&mut self, celsius: f32) {
85	        self.temperature = celsius;
86	    }
87	
88	    /// Currently-configured temperature in °C (the value the guest
89	    /// would read back, given the current resolution).
90	    pub fn temperature(&self) -> f32 {
91	        let val = self.temp_register_value();
92	        // Sign-extend the 12-bit value to i32, scale by 0.0625°C/LSB.
93	        let signed = sign_extend_12(val);
94	        signed as f32 * 0.0625
95	    }
96	
97	    /// Set the configuration register directly. Useful in tests.
98	    pub fn set_config(&mut self, config: u8) {
99	        self.config = config;
100	    }
101	
102	    pub fn config(&self) -> u8 {
103	        self.config
104	    }
105	
106	    /// Set the resolution by writing the appropriate bits to config.
107	    /// Other config bits are preserved.
108	    pub fn set_resolution(&mut self, res: Tmp101Resolution) {
109	        let bits: u8 = match res {
110	            Tmp101Resolution::Bits9 => 0b00,
111	            Tmp101Resolution::Bits10 => 0b01,
112	            Tmp101Resolution::Bits11 => 0b10,
113	            Tmp101Resolution::Bits12 => 0b11,
114	        };
115	        self.config = (self.config & !0x60) | (bits << 5);
116	    }
